'use client'

import { createContext, useContext, useState } from 'react'
import type { Dispatch, ReactNode, SetStateAction } from 'react'

type Theme = 'light' | 'dark'

interface AppContextValue {
  theme: Theme
  setTheme: Dispatch<SetStateAction<Theme>>
}

const AppContext = createContext<AppContextValue | undefined>(undefined)

export function AppProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>('light')

  return (
    <AppContext.Provider value={{ theme, setTheme }}>
      {children}
    </AppContext.Provider>
  )
}

export function useAppContext(): AppContextValue {
  const context = useContext(AppContext)
  if (!context) {
    throw new Error('useAppContext must be used within AppProvider')
  }
  return context
}
export interface BlogPost {
  userId: number
  id: number
  title: string
  body: string
}

export interface BlogComment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

type FetchPolicy = { revalidate: number } | { cache: 'no-store' }

const API_URL = 'https://jsonplaceholder.typicode.com'

async function fetchJson<T>(url: string, policy: FetchPolicy): Promise<T> {
  const response = await fetch(
    url,
    'revalidate' in policy
      ? { next: { revalidate: policy.revalidate } }
      : { cache: policy.cache }
  )

  if (!response.ok) {
    throw new Error(`Request failed (${response.status}): ${url}`)
  }

  return (await response.json()) as T
}

export function getBlogPosts(
  policy: FetchPolicy,
  limit?: number
): Promise<BlogPost[]> {
  const query = limit ? `?_limit=${limit}` : ''
  return fetchJson<BlogPost[]>(`${API_URL}/posts${query}`, policy)
}

export async function getBlogPost(
  id: string,
  policy: FetchPolicy
): Promise<BlogPost | null> {
  const url = `${API_URL}/posts/${encodeURIComponent(id)}`
  const response = await fetch(
    url,
    'revalidate' in policy
      ? { next: { revalidate: policy.revalidate } }
      : { cache: policy.cache }
  )

  if (response.status === 404) {
    return null
  }

  if (!response.ok) {
    throw new Error(`Request failed (${response.status}): ${url}`)
  }

  const post: unknown = await response.json()
  if (!isBlogPost(post)) {
    return null
  }

  return post
}

export function getBlogComments(
  id: string,
  policy: FetchPolicy
): Promise<BlogComment[]> {
  return fetchJson<BlogComment[]>(
    `${API_URL}/posts/${encodeURIComponent(id)}/comments`,
    policy
  )
}

function isBlogPost(value: unknown): value is BlogPost {
  return (
    typeof value === 'object' &&
    value !== null &&
    'id' in value &&
    typeof value.id === 'number' &&
    'userId' in value &&
    typeof value.userId === 'number' &&
    'title' in value &&
    typeof value.title === 'string' &&
    'body' in value &&
    typeof value.body === 'string'
  )
}
import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BackButton from '../../../components/BackButton'
import { getBlogComments, getBlogPost, getBlogPosts } from '../../../lib/blog'

export const revalidate = 300
export const dynamicParams = true

type BlogPostPageProps = {
  params: Promise<{ id: string }>
}

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getBlogPosts({ revalidate: 300 })

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getBlogPost(id, { revalidate: 300 })

  if (!post) {
    return { title: { absolute: '404 - Page Not Found' } }
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: `${post.title} - My Blog`,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const [post, comments] = await Promise.all([
    getBlogPost(id, { revalidate: 300 }),
    getBlogComments(id, { revalidate: 300 }),
  ])

  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
